INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 110501, 0, 24015, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 1, 4, 24, "2030/12/17 14:59:59", 4);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 110501, 4, 24016, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 2, 1, 24, "2030/12/17 14:59:59", 4);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("マジムンだらけで目が回るさ～！\nふらふらさ～！", 110501, 0, 24017, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 3, 4, 24, "2030/12/17 14:59:59", 4);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 110501, 5.2, 24018, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 4, 2, 24, "2030/12/17 14:59:59", 1);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 110501, 4.2, 24019, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 5, 6, 24, "2030/12/17 14:59:59", 5);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 110501, 0, 24020, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 6, 2, 24, "2030/12/17 14:59:59", 2);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 110501, 6.4, 24021, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 7, 6, 24, "2030/12/17 14:59:59", 1);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 110501, 0, 24022, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 8, 2, 24, "2030/12/17 14:59:59", 2);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 110501, 10.08, 24023, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 9, 3, 24, "2030/12/17 14:59:59", 6);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 110501, 5, 24024, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 10, 2, 24, "2030/12/17 14:59:59", 1);
INSERT INTO `v1_026c06e9dfdfbce9ab3d23523fe0bfba78c4cfdaae70641be1a65efcbb3d6b47` VALUES ("私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 110501, 0, 24025, "2019/07/31 12:00:00", 10021, 0, "カオリ（サマー）", 0, 11, 2, 24, "2030/12/17 14:59:59", 2);
